<script setup>
/**
 * /lessons/ page body: a hero title band (same fixed-dark-navy/radial-glow/
 * dot-grid treatment as AboutPage.vue's .about-hero, reusing the same
 * "hero + centered 80rem section" pattern so the two pages read as one
 * site), then a "Your Learning Path" grid covering every track in
 * curriculum.ts, real brand mark, real color, and a "Soon" badge for every
 * "comingSoon" track. The glowing skill-card visual treatment is
 * the same one the home page's "What you'll learn" section uses (colors/icons duplicated from
 * HomeSections.vue on purpose: this is a second, differently-framed
 * presentation of the same tracks, not a reusable shared component, so a
 * hand-tuned copy here doesn't churn if the home page's own version changes
 * independently).
 *
 * This page previously rendered just the five ready tracks here, plus a
 * separate, commented-out "All Sections" block below the grid for the full
 * per-lesson curriculum breakdown. That second block is gone now that this
 * grid itself covers every track (not just the ready five), which is what
 * it existed to show in the first place.
 *
 * Motion is the home page's (see HomeSections.vue): AOS fades the title
 * and intro in, usePageMotion runs the hero entrance, rises the track
 * cards in (`.motion-card`) and scrambles each title's `.heading-accent`.
 *
 * A short FAQ closes the page, using the home page's accordion
 * (FaqAccordion.vue) with questions about picking and moving through
 * tracks.
 */
import { ref } from 'vue';
import { withBase } from 'vitepress';
import { useAos } from '../composables/useAos';
import { usePageMotion } from '../composables/usePageMotion';
import FaqAccordion from './FaqAccordion.vue';
import { curriculum, firstLessonPath } from '../data/curriculum';

// Real brand mark + real brand color for every track, ready or
