	return {
		slug: track.slug,
		title: track.title,
		href: withBase(firstLessonPath(track)),
		comingSoon: !!track.comingSoon,
		// Fallback path only matters if a future track is added to
		// curriculum.ts before a matching entry lands above.
		color: meta ? meta.color : '#64748b',
		icon: meta ? meta.icon : null,
		monogram: meta ? null : track.title.slice(0, 2).toUpperCase(),
